{"path":"assets/css/styles.css","content":"/* Zen Minimal styles — crisp spacing, neutral palette */
:root{
  --bg:#fbfbfb;
  --surface:#ffffff;
  --muted:#7b7b7b;
  --text:#202020;
  --accent:#2b8a78;
  --accent-2:#e6f7f2;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max-width);margin:0 auto;padding:48px 24px}
.header-row{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;gap:12px;align-items:center}
.brand .logo{width:44px;height:44px}
.brand-text strong{display:block}
.brand-text small{display:block;color:var(--muted);font-size:12px}
.nav{display:flex;gap:18px;align-items:center}
.nav a{color:var(--text);text-decoration:none;font-weight:600}
.nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.nav-toggle{display:none;border:0;background:none;font-size:20px}

.hero{position:relative;padding:80px 0 60px;background:linear-gradient(180deg,transparent 0%, rgba(230,247,242,0.6) 100%)}
.hero-graphic{position:absolute;right:0;top:0;opacity:0.65;width:420px;max-width:50%;pointer-events:none}
.hero-inner{display:flex;align-items:center;min-height:320px}
.hero-copy{max-width:640px}
.hero h1{font-size:38px;margin:0 0 12px}
.lead{color:var(--muted);font-size:16px;margin-bottom:18px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;border:1px solid transparent;background:var(--surface);color:var(--text);font-weight:600}
.btn.ghost{background:transparent;border-color:transparent}
.btn.primary{background:var(--accent);color:#fff}
.btn.small{padding:8px 12px}
.hero-ctas{display:flex;gap:12px;margin-bottom:12px}
.lead-magnet label{display:block;font-size:13px;color:var(--muted);margin-bottom:8px}
.form-row{display:flex;gap:8px}
.form-row input{flex:1;padding:10px;border-radius:8px;border:1px solid #e6e6e6}

.story-grid{display:grid;grid-template-columns:120px 1fr;gap:18px;align-items:center}
.avatar img{width:120px;height:120px;border-radius:12px;border:1px solid #eee}
.story h2{margin-top:0}
.muted{color:var(--muted);font-size:13px}

.framework .cards{display:flex;gap:18px;margin-top:18px}
.card{background:var(--surface);padding:18px;border-radius:12px;box-shadow:0 4px 10px rgba(30,30,30,0.04);flex:1}

.program-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:18px}
.program{background:var(--surface);padding:18px;border-radius:12px}
.program .link{display:inline-block;margin-top:12px;color:var(--accent)}

.pricing-grid{display:flex;gap:12px;flex-wrap:wrap;margin-top:12px}
.price-card{flex:1;min-width:200px;background:linear-gradient(180deg,#fff,#fbfffc);padding:18px;border-radius:12px;border:1px solid #f0f0f0}
.price{font-size:22px;font-weight:700;margin:8px 0}

.testimonials-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:12px}
.testimonials-grid blockquote{background:var(--surface);padding:14px;border-radius:10px;border-left:4px solid var(--accent-2);color:var(--muted)}

.final-cta{background:var(--accent-2);padding:28px;border-radius:12px;text-align:center;margin-top:24px}

.site-footer{padding:28px 24px;color:var(--muted)}
.footer-grid{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.footer-grid a{color:var(--muted);text-decoration:none}

@media(max-width:800px){
  .nav{display:none}
  .nav-toggle{display:block}
  .hero-graphic{display:none}
  .wrap{padding:28px 18px}
  .header-row{padding:12px 0}
  .story-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple nav toggle
  var btn=document.getElementById('navToggle');
  var nav=document.querySelector('.nav');
  btn&&btn.addEventListener('click',function(){
    if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex';nav.style.flexDirection='column';nav.style.gap='12px'}
  });

  // Lead magnet form handling — prevents navigation and simulates success
  var leadForm=document.getElementById('leadForm');
  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email=document.getElementById('emailInput').value;
      if(!email) return;
      leadForm.querySelector('button').textContent='Sending...';
      setTimeout(function(){
        leadForm.innerHTML='<p class="muted">Thanks — the 5-day guide is on its way to '+(email)+'.</p>';
      },800);
    });
  }

  // Smooth scroll for in-page links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var tgt=document.querySelector(this.getAttribute('href'));
      if(tgt){e.preventDefault();tgt.scrollIntoView({behavior:'smooth',block:'start'})}
    });
  });
})();
"} 
